    @inline(__always)
    private func checkMultiplyingWhereConstantAAlternating(_ even: Lane, _ odd: Lane) {
        let mismatches = Mismatches("multiplyingWhere with a alternating \(hex(even)), \(hex(odd))")
        let maskInputs = Inputs.masks(H.Mask.self, seed: 0x08AB_79CB_41CF_E921)
        let bInputs = Inputs.vectors(H.self, seed: 0x08AB_77CB_41CF_E5BB)
        mismatches.check(
            H.repeatingBlock(even, odd, even, odd, even, odd, even, odd),
            H(
                raw: HighwayReference.repeatingBlockF16(
                    even.bitPattern,
                    odd.bitPattern,
                    even.bitPattern,
                    odd.bitPattern,
                    even.bitPattern,
                    odd.bitPattern,
                    even.bitPattern,
                    odd.bitPattern
                )
            ),
            "repeatingBlock"
        )
        for (mask, b) in everyPair(maskInputs, bInputs)
        where !hasUnorderedNaNs(
            H.repeatingBlock(even, odd, even, odd, even, odd, even, odd).simd,
            b.simd
        ) {
            mismatches.check(
                H.multiplying(
                    H.repeatingBlock(even, odd, even, odd, even, odd, even, odd),
                    b,
                    where: mask
                ),
                H(
                    raw: HighwayReference.multiplyingWhereF16(
                        mask.raw,
                        H.repeatingBlock(even, odd, even, odd, even, odd, even, odd).raw,
                        b.raw
                    )
                ),
                "mask: \(describe(mask)), b: \(describe(b))"
            )
        }
        mismatches.record()
    }

